examples.code:
S = [2 1; 1 2];
[T, num] = cholcov(S);
disp(round(T*10000)/10000)
disp(num)
disp(round(T'*T*10000)/10000)

S = [4 2 0; 2 3 0; 0 0 0];
[T, num] = cholcov(S);
disp(size(T))
disp(num)
disp(round(T'*T*10000)/10000)

N = [1 2; NaN 3; 4 6; 5 NaN; 7 9];
disp(round(corr(N, 'rows', 'pairwise')*10000)/10000)
x = (1:6)'; y = [2 1 4 3 7 5]';
fprintf('%.4f\n', corr(x, y, 'type', 'Spearman'))

c = {'a','b','a','c'}';
[t, chi2, p, lab] = crosstab(c, [1 2 1 2]');
disp(t)
disp(lab(:,1)')

y = [1 2 3 4 10];
s = moment(y, 3) / moment(y, 2)^1.5;
fprintf('%.4f %.4f\n', s, skewness(y))

N = [1 NaN 3; 4 5 NaN; 7 8 9; NaN 2 1];
disp(nanmax(N))
[m, ix] = nanmax(N);
disp(ix)
disp(nanmax(N, [], 2)')

N = [1 NaN 3; 4 5 NaN; 7 8 9; NaN 2 1];
disp(nanmean(N))
disp(nanmean(N, 2)')

N = [1 NaN 3; 4 5 NaN; 7 8 9; NaN 2 1];
disp(nanmedian(N))
disp(nanmedian(N, 2)')

N = [1 NaN 3; 4 5 NaN; 7 8 9; NaN 2 1];
disp(nanmin(N))
[m, ix] = nanmin(N);
disp(ix)
disp(nanmin(N, [], 2)')

N = [1 NaN 3; 4 5 NaN; 7 8 9; NaN 2 1];
disp(round(nanstd(N)*10000)/10000)
disp(round(nanstd(N, 1)*10000)/10000)

N = [1 NaN 3; 4 5 NaN; 7 8 9; NaN 2 1];
disp(round(nanvar(N)*10000)/10000)
disp(round(nanvar(N, 1)*10000)/10000)

x = (1:6)'; y = [2 1 4 3 7 5]'; z = [1 1 2 2 3 3]';
fprintf('%.4f\n', corr(x, y))
[r, p] = partialcorr(x, y, z);
fprintf('%.4f %.4f\n', r, p)

A = [2 4 6; 3 1 8; 5 7 2; 9 3 4; 1 6 5];
[z, mu, sigma] = zscore(A);
disp(round(z*10000)/10000)
disp(mu)
disp(round(sigma*10000)/10000)
